A minimal AWS provider + resource:
# main.tf
terraform {
required_version = ">= 1.5"
required_providers {
aws = {
source = "hashicorp/aws"
version = "~> 5.0"
}
}
}
provider "aws" {
region = "ap-east-1"
}
resource "aws_s3_bucket" "demo" {
bucket = "course-demo-2026-${random_id.b.hex}"
}
resource "random_id" "b" {
byte_length = 4
}
Workflow:
terraform init # download providers
terraform plan # show what would change
terraform apply # make it happen (prompts to confirm)
terraform destroy # tear it all down

variable "region" {
type = string
default = "ap-east-1"
}
variable "az_count" {
type = number
default = 3
}
provider "aws" { region = var.region }
Pass at apply time:
terraform apply -var="region=us-east-1"
# or
terraform apply -var-file=prod.tfvars

output "bucket_name" {
value = aws_s3_bucket.demo.bucket
}
Print with terraform output bucket_name after apply.

locals {
prefix = "${var.environment}-myapp"
common_tags = {
Environment = var.environment
ManagedBy = "terraform"
Owner = "team-platform"
}
}

A module is a reusable bundle of resources. The full 3-AZ VPC from Post 01 can be a module:
# modules/vpc/main.tf
variable "cidr" { type = string }
variable "azs" { type = list(string) }
variable "name" { type = string }
resource "aws_vpc" "this" {
cidr_block = var.cidr
tags = { Name = var.name }
}
resource "aws_subnet" "public" {
for_each = toset(var.azs)
vpc_id = aws_vpc.this.id
cidr_block = cidrsubnet(var.cidr, 8, index(var.azs, each.value))
availability_zone = each.value
tags = { Name = "${var.name}-public-${each.value}" }
}
# ... private, isolated subnets, IGW, NAT, route tables ...
output "vpc_id" { value = aws_vpc.this.id }
output "public_subnet_ids" { value = [for s in aws_subnet.public : s.id] }
Consume:
module "vpc" {
source = "./modules/vpc"
name = "prod"
cidr = "10.0.0.0/16"
azs = ["ap-east-1a", "ap-east-1b", "ap-east-1c"]
}
output "vpc_id" { value = module.vpc.vpc_id }

By default Terraform stores state locally in terraform.tfstate. For teams, store it in S3 + a DynamoDB lock table:
terraform {
backend "s3" {
bucket = "myorg-tfstate"
key = "prod/network/terraform.tfstate"
region = "us-east-1"
encrypt = true
dynamodb_table = "myorg-tfstate-lock"
}
}
Setup once: create the bucket + lock table by hand (or with a tiny bootstrap Terraform run). Then every subsequent project uses the backend.
Watch out: the state file contains every value — including secrets you passed to resources. Encrypt the bucket, restrict access tightly, and treat state with the same care as a database backup.
